import click

# Let's check if Click 8 supports custom help formatting
# by overriding the format_options method

class CustomGroup(click.Group):
    def format_options(self, ctx, formatter):
        """Custom format options to show them under categories."""
        # First, group options by category
        categories = {}
        for param in self.params:
            category = getattr(param, 'category', 'Other')
            if category not in categories:
                categories[category] = []
            categories[category].append(param)

        # Print categories and options
        for category, params in sorted(categories.items()):
            formatter.write(f"{category}:\n")
            for param in sorted(params, key=lambda p: p.name):
                help_text = param.get_help_record({})
                if help_text:
                    formatter.write(f"  {help_text[0]}")
                    if len(help_text) > 1:
                        formatter.write(f"  {help_text[1]}")
                    formatter.write('\n')
            formatter.write('\n')

# Test
@click.group(cls=CustomGroup)
def cli():
